static bool32 SaveOnMysteryGiftMenu(u8 *state)
{
    switch (*state)
    {
    case 0:
        MG_AddMessageTextPrinter(gText_DataWillBeSaved);
        (*state)++;
        break;
    case 1:
        TrySavingData(SAVE_NORMAL);
        (*state)++;
        break;
    case 2:
        MG_AddMessageTextPrinter(gText_SaveCompletedPressA);
        (*state)++;
        break;
    case 3:
        if (JOY_NEW(A_BUTTON | B_BUTTON))
            (*state)++;
        break;
    case 4:
        *state = 0;
        ClearMessage();
        return TRUE;
    }

    return FALSE;
}

